d="M32 24H500M32 68H500M32 112H500" /><path class="lifecycle-line" d="M32 104 C105 98 130 72 190 78 S275 94 330 57 S410 42 488 25" /><circle class="point" cx="32" cy="104" r="5" /><circle class="point" cx="190" cy="78" r="5" /><circle class="point" cx="330" cy="57" r="5" /><circle class="point current" cx="488" cy={heroStep === 2 ? 25 : heroStep === 1 ? 57 : 78} r="7" /></svg></div><pre><code><span class="muted">&lt;script&gt;</span>
